  event_id INT UNSIGNED NULL COMMENT 'Internal FK to calendar_events.id; nullable so audit-trail comments survive event hard-delete (FK SET NULL)',
  author_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  body MEDIUMTEXT NOT NULL COMMENT 'Comment text (markdown)',
  edited_at DATETIME(3) NULL COMMENT 'Last edit time (null = never edited)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  deleted_at DATETIME(3) NULL DEFAULT NULL COMMENT 'Soft-delete timestamp; rows with deleted_at IS NOT NULL are excluded from LIST/GET',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendar_event_comments_public_id (public_id),
  UNIQUE KEY uniq_calendar_event_comments_workspace_public_id (workspace_id, public_id),
  KEY idx_calendar_event_comments_event (workspace_id, event_id, created_at),
  KEY idx_calendar_event_comments_workspace_author (workspace_id, author_id),
  KEY idx_calendar_event_comments_deleted_at (deleted_at),

  CONSTRAINT fk_calendar_event_comments_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_event_comments_event FOREIGN KEY (event_id) REFERENCES calendar_events(id) ON DELETE SET NULL,
  CONSTRAINT fk_calendar_event_comments_author FOREIGN KEY (author_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Calendar event discussion comments';

-- >>> calendar_event_invites.sql
-- ====================================
-- calendar_event_invites
-- Magic-link invite rows issued to calendar event attendees.
-- Each row carries a SHA-256 token hash and expiry so an unauthenticated
-- recipient can click the link, be identified as the intended attendee,
-- and update their RSVP. The plaintext token is never stored.
--
-- Lifecycle:
--   1. insert    : token_hash + expires_at set; sent_at / accepted_at NULL
--   2. dispatch  : sent_at set when the email is actually delivered
--   3. accept    : accepted_at set when the recipient opens the link
--   4. resend    : update the existing row in place (rotate token_hash,
--                  bump expires_at, clear sent_at / accepted_at) to respect
--                  the (event_id, attendee_id) uniqueness constraint.
-- ====================================
CREATE TABLE calendar_event_invites (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  calendar_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendars.id',
  event_id INT UNSIGNED NULL COMMENT 'Internal FK to calendar_events.id; nullable so revoked invites survive event hard-delete (FK SET NULL)',
  attendee_id INT UNSIGNED NULL COMMENT 'Internal FK to calendar_event_attendees.id; nullable to mirror parent attendee being detached on event hard-delete',

  email VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Recipient email, denormalized from attendee for inbox queries',
  token_hash BINARY(32) NOT NULL COMMENT 'SHA-256 digest of the plaintext magic-link token',
  expires_at DATETIME(3) NOT NULL COMMENT 'Magic-link expiry',
  accepted_at DATETIME(3) NULL COMMENT 'Set when the recipient clicks the link',
  sent_at DATETIME(3) NULL COMMENT 'Set when the invite email is dispatched',

  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag; disabled rows are revoked invites',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendar_event_invites_public_id (public_id),
  UNIQUE KEY uniq_calendar_event_invites_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_calendar_event_invites_token_hash (token_hash),
  UNIQUE KEY uniq_calendar_event_invites_event_attendee (event_id, attendee_id),
  KEY idx_calendar_event_invites_workspace_expires (workspace_id, expires_at),
  KEY idx_calendar_event_invites_workspace_email (workspace_id, email),
  KEY idx_calendar_event_invites_calendar_id (calendar_id),
  KEY idx_calendar_event_invites_attendee_id (attendee_id),

  CONSTRAINT fk_calendar_event_invites_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_event_invites_calendar FOREIGN KEY (calendar_id) REFERENCES calendars(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_event_invites_event FOREIGN KEY (event_id) REFERENCES calendar_events(id) ON DELETE SET NULL,
  CONSTRAINT fk_calendar_event_invites_attendee FOREIGN KEY (attendee_id) REFERENCES calendar_event_attendees(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Magic-link invite rows for calendar event attendees';

-- >>> calendar_events.sql
-- ====================================
-- calendar_events
-- Calendar events with kind/visibility/show_as classification; nullable
-- start/end for planning-stage placeholders; task_role links to task
-- projection (D1).
-- ====================================
CREATE TABLE calendar_events (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  calendar_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendars.id',

  -- Event classification
  kind ENUM('event','block','free','milestone') NOT NULL DEFAULT 'event' COMMENT 'event=regular, block=declarative time frame (work hours, focus), free=available slot, milestone=umbrella/milestone, has no duration semantics',
  visibility ENUM('default','public','private','confidential') NOT NULL DEFAULT 'default' COMMENT 'Who can see event details: default (calendar setting), public (all), private (time only), confidential (owner only)',
  show_as ENUM('busy','free','tentative','oof') NOT NULL DEFAULT 'busy' COMMENT 'Availability display: busy, free, tentative, out-of-office. The iCalendar TRANSP axis — whether the time reads as taken — and nothing more.',
  /**
   * flexibility: whether a confirmed commitment could be moved, which
   * show_as cannot express. A meeting the owner would happily reschedule
   * and one that cannot move are both show_as='busy'; treating either as
   * simply unavailable is what makes coordinating across calendars a
   * conversation rather than a lookup.
   *
   * The two axes stay separate on purpose. Overloading show_as with
   * movability would put non-iCalendar values into the column every
   * external consumer reads as TRANSP, so a free/busy export would start
   * lying to anyone outside this database.
   *
   *   fixed        cannot move (default; the safe reading of a row
   *                written by anything that predates this column)
   *   negotiable   the owner is willing to move it
   *   conditional  movable, but subject to something outside this row —
   *                another party's agreement, a cost, a dependency
   */
  flexibility ENUM('fixed','negotiable','conditional') NOT NULL DEFAULT 'fixed' COMMENT 'Whether the commitment can be moved, independent of whether the time reads as busy. Combined with show_as to derive a displayed availability mark.',

  title VARCHAR(500) NOT NULL COMMENT 'Event title',
  all_day BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'All-day event flag',
  start_at DATETIME(3) NULL COMMENT 'Start time (UTC or with timezone context); NULL = undated (planning-stage placeholder)',
  end_at DATETIME(3) NULL COMMENT 'End time; NULL = undated (planning-stage placeholder)',
  timezone VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'UTC' COMMENT 'IANA timezone identifier; resolved from event > user > workspace > UTC',

  location VARCHAR(500) NULL COMMENT 'Location text',
  memo MEDIUMTEXT NULL COMMENT 'Free-form notes (markdown)',
  url VARCHAR(2048) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'Meeting link or related URL',

  -- Ownership: determines whose layer this event belongs to
  owner_user_id INT UNSIGNED NOT NULL COMMENT 'Event owner (whose color/layer). Only owner, managers, or can_edit attendees may edit',
  created_by_user_id INT UNSIGNED NOT NULL COMMENT 'Actual creator (may differ from owner for manager delegation)',

  -- Block metadata
  block_label VARCHAR(100) NULL COMMENT 'Label for block-kind events (e.g., Working, Focus Time, Out of Office)',

  -- Recurrence (RFC 5545 subset stored as JSON)
  recurrence_rule JSON NULL COMMENT 'Recurrence rule: {freq, interval, byDay, byMonthDay, bySetPos, until, count}',
  recurrence_end DATETIME(3) NULL COMMENT 'Computed end date for recurrence expansion queries',
  recurrence_exceptions JSON DEFAULT NULL COMMENT 'Array of ISO 8601 occurrence starts to skip when expanding this rule. Cancelling one occurrence is an entry here, never a row.',
  /**
   * A recurring series is one row plus two ways of departing from it,
   * and they are not interchangeable:
   *
   *   cancel one occurrence  -> add its start to recurrence_exceptions
   *   change one occurrence  -> a second row naming this one as parent
   *
   * Splitting them this way keeps exactly one representation of each
   * outcome. Allowing a row to also mean "cancelled" would give a
   * consumer two places to look before it could say whether an
   * occurrence happens, and the two would eventually disagree.
   *
   * An override row carries the changed occurrence in the ordinary
   * columns and has no recurrence_rule of its own; it is a leaf.
   */
  recurrence_parent_id INT UNSIGNED NULL COMMENT 'Set on an override row: the recurring event whose single occurrence this row replaces. NULL on ordinary and master rows.',
  recurrence_original_start DATETIME(3) NULL COMMENT 'Set on an override row: the start the occurrence would have had under the parent rule. Identifies which occurrence is replaced, so moving the override does not lose track of what it overrides.',

  notification_offset INT NULL COMMENT 'Minutes before event to send notification; NULL = no notification',
  notified_at DATETIME(3) NULL DEFAULT NULL COMMENT 'Timestamp when notification was sent; NULL = not yet notified',

  -- Cross-module link to nodate-flow tasks
  task_id INT UNSIGNED NULL COMMENT 'Linked task (optional, for task-calendar sync)',
  task_role ENUM('due','scheduled') NULL COMMENT 'When task_id IS NOT NULL: which task field this event represents. due=task.due_on, scheduled=time-blocked (multi-link allowed).',
  /**
   * task_role_key: de-NULLed projection of task_role used to build a UNIQUE
   * key over (task_id, task_role). MySQL UNIQUE indexes treat NULLs as
   * distinct, which would let two NULL task_role rows coexist for the same
   * task_id and silently weaken the (task_id, task_role) invariant. By
   * coalescing NULL to the empty string in a STORED generated column we get
   * a NOT NULL surrogate that participates in the UNIQUE without losing the
   * "absent role" sentinel.
   */
  task_role_key VARCHAR(32) GENERATED ALWAYS AS (COALESCE(task_role, '')) STORED NOT NULL COMMENT 'De-NULLed surrogate for task_role; empty string when task_role IS NULL. Exists solely to power uniq_calendar_events_task_role_key over (task_id, task_role_key).',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  flags JSON NULL COMMENT 'Structured per-event markers (non_working_day, auto_snapped, etc.); unknown keys preserved.',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Soft-delete flag; FALSE excludes the row from LIST/GET. The single soft-delete signal for this table — propagate via INNER/LEFT JOIN ... AND ce.enabled = TRUE in every consumer view, so a soft-deleted row cannot reappear through a join.',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendar_events_public_id (public_id),
  UNIQUE KEY uniq_calendar_events_workspace_public_id (workspace_id, public_id),
  KEY idx_calendar_events_calendar_range (calendar_id, start_at, end_at),
  KEY idx_calendar_events_workspace_owner (workspace_id, owner_user_id, start_at),
  KEY idx_calendar_events_calendar_recurrence (calendar_id, recurrence_end),
  KEY idx_calendar_events_workspace_range (workspace_id, start_at, end_at),
  KEY idx_calendar_events_task_role (task_id, task_role, enabled),
  UNIQUE KEY uniq_calendar_events_task_role_key (task_id, task_role_key),
  -- One override per occurrence. Without this, two concurrent edits of
  -- the same occurrence both insert, and the expander has to pick.
  UNIQUE KEY uniq_calendar_events_recurrence_override (recurrence_parent_id, recurrence_original_start),
  FULLTEXT KEY ft_calendar_events_title_memo (title, memo),

  CONSTRAINT fk_calendar_events_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_events_calendar FOREIGN KEY (calendar_id) REFERENCES calendars(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_events_owner FOREIGN KEY (owner_user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_events_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE CASCADE,
  -- CASCADE: an override has no meaning once the series it departs from
  -- is gone, and leaving it behind would surface a stray one-off event
  -- on someone's calendar long after they deleted the series.
  CONSTRAINT fk_calendar_events_recurrence_parent FOREIGN KEY (recurrence_parent_id) REFERENCES calendar_events(id) ON DELETE CASCADE,
  -- fk_calendar_events_task (task_id -> tasks.id) is NOT declared here.
  -- task_id is a core column so that every deployment writes rows of the
  -- same shape, but `tasks` belongs to a product layer and a foreign key
  -- cannot point at a table that may not exist. The layer owning `tasks`
  -- adds the constraint from its own constraints/ directory; where there
  -- is no such layer, task_id is always NULL.

  -- CHECK constraints that do not reference task_id. MySQL 8.4+
  -- forbids CHECK constraints referencing columns used in FK
  -- referential actions (task_id has ON DELETE SET NULL), so these
  -- two invariants live in trg_calendar_events_projection_guard_ins /
  -- _upd, which have no such restriction:
  --   (task_id IS NULL) = (task_role IS NULL)
  --   task_id IS NULL OR recurrence_rule IS NULL
  -- The same triggers reserve task_id, task_role, title, start_at,
  -- end_at and enabled on a projected row for the projection engine.
  CONSTRAINT chk_calendar_events_start_end_pair CHECK (start_at IS NULL OR end_at IS NOT NULL),
  CONSTRAINT chk_calendar_events_recurrence_requires_start CHECK (start_at IS NOT NULL OR recurrence_rule IS NULL),
  CONSTRAINT chk_calendar_events_notification_requires_start CHECK (start_at IS NOT NULL OR notification_offset IS NULL),
  CONSTRAINT chk_calendar_events_chronology CHECK (end_at IS NULL OR start_at IS NULL OR end_at >= start_at),
  CONSTRAINT chk_calendar_events_milestone_no_recurrence CHECK (kind <> 'milestone' OR recurrence_rule IS NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Calendar events with kind/visibility/show_as classification; nullable start/end for planning-stage placeholders; task_role links to task projection. Soft-delete is signalled solely by enabled=FALSE (no deleted_at column); consumer views must propagate enabled=TRUE on every JOIN to honour soft-delete.';

-- >>> calendar_members.sql
-- ====================================
-- calendar_members
-- Who may see a calendar, and what they may do with it.
--
-- This is an ACL axis, unlike calendar_subscriptions, which holds one
-- subscriber's private display preferences and deliberately grants
-- nothing. Two tables because the questions are different: membership is
-- shared state that the calendar's owner controls, a subscription is
-- personal state its own user controls, and letting one row answer both
-- means changing your sidebar colour is a permission write.
--
-- Workspace membership is a prerequisite, not a substitute. A workspace
-- may hold several calendars whose audiences do not coincide, so being in
-- the workspace says a member could be given access, and a row here says
-- they were.
--
-- Roles are ordered: owner > manager > editor > viewer. Read them as
--   owner    controls membership and can delete the calendar
--   manager  controls membership, cannot delete the calendar
--   editor   writes events
--   viewer   reads
-- Callers must resolve through the calendar resolution helpers rather
-- than reading this table directly, because the lookup and the role check
-- belong together — separating them is how an authorization check gets
-- skipped without anyone noticing.
-- ====================================
CREATE TABLE calendar_members (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  calendar_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendars.id',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  role ENUM('owner','manager','editor','viewer') NOT NULL DEFAULT 'viewer' COMMENT 'What this member may do with the calendar. Defaults to the least privilege so a writer that omits it cannot accidentally grant access.',

  -- The colour everyone sees for this member's events, as distinct from
  -- calendar_subscriptions.display_color, which is one subscriber's
  -- private override for a whole calendar. On a shared calendar the point
  -- is telling people apart, which only works if the assignment is agreed
  -- rather than per-viewer.
  member_color VARCHAR(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '#4285F4' COMMENT 'Shared colour identifying this member on the calendar; agreed rather than per-viewer, unlike calendar_subscriptions.display_color',

  invited_by_user_id INT UNSIGNED NULL COMMENT 'Internal FK to users.id; who granted this membership. NULL for the owner row created with the calendar.',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Soft-delete flag; FALSE means the membership was revoked. Every access check must filter on enabled = TRUE.',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendar_members_public_id (public_id),
  UNIQUE KEY uniq_calendar_members_workspace_public_id (workspace_id, public_id),
  -- One row per (calendar, user) regardless of enabled, so re-adding a
  -- removed member updates the existing row rather than accumulating
  -- revoked duplicates that a future access check might read.
  UNIQUE KEY uniq_calendar_members_calendar_user (calendar_id, user_id),
  KEY idx_calendar_members_user_workspace (user_id, workspace_id, enabled),
  KEY idx_calendar_members_calendar_role (calendar_id, role, enabled),

  CONSTRAINT fk_calendar_members_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_members_calendar FOREIGN KEY (calendar_id) REFERENCES calendars(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_members_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_members_invited_by FOREIGN KEY (invited_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Per-calendar access grants: which users may use a calendar and at what role. The ACL axis, unlike calendar_subscriptions, which holds private display preferences and grants nothing.';

-- >>> calendar_memos.sql
-- ====================================
-- calendar_memos
-- Shared to-do / memo items pinned to a calendar. TimeTree-compatible
-- feature for lightweight shared checklists that aren't tied to a
-- specific event.
-- ====================================
CREATE TABLE calendar_memos (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  calendar_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendars.id',
  created_by_user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  title VARCHAR(500) NOT NULL COMMENT 'Memo text',
  body TEXT NULL COMMENT 'User-authored multi-line memo body, distinct from admin notes',
  done BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Completion flag',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendar_memos_public_id (public_id),
  UNIQUE KEY uniq_calendar_memos_workspace_public_id (workspace_id, public_id),
  KEY idx_calendar_memos_calendar (calendar_id, sort_weight),
  KEY idx_calendar_memos_workspace (workspace_id, calendar_id),
  KEY idx_calendar_memos_creator (workspace_id, created_by_user_id),

  CONSTRAINT fk_calendar_memos_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_memos_calendar FOREIGN KEY (calendar_id) REFERENCES calendars(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_memos_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Calendar-level shared memos / to-do items';

-- >>> calendar_public_share_events.sql
-- ====================================
-- calendar_public_share_events
-- M:N between calendar_public_shares and calendar_events. Row
-- existence = opt-in for external visibility on that specific share
-- page. One event can appear on multiple shares (e.g. joint concerts
-- listed under two artist pages); removing a row unpublishes without
-- affecting internal visibility.
-- ====================================
CREATE TABLE calendar_public_share_events (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id; denormalized from share for tenant isolation',
  share_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendar_public_shares.id',
  event_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendar_events.id',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Override display order on the share page',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag (soft-disable)',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendar_public_share_events_public_id (public_id),
  UNIQUE KEY uniq_calendar_public_share_events_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_calendar_public_share_events_share_event (share_id, event_id, enabled) COMMENT 'At most one enabled publication per (share, event)',
  KEY idx_calendar_public_share_events_workspace_event (workspace_id, event_id, enabled),

  CONSTRAINT fk_calendar_public_share_events_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_public_share_events_share FOREIGN KEY (share_id) REFERENCES calendar_public_shares(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_public_share_events_event FOREIGN KEY (event_id) REFERENCES calendar_events(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='M:N: which events appear on which public share pages';

-- >>> calendar_public_shares.sql
-- ====================================
-- calendar_public_shares
-- Workspace-owned publishable read-only pages. Any ws non-guest member
-- can create/edit; delete is admin-only to prevent accidental URL loss.
-- Token is stored as SHA-256 hash; plaintext is returned exactly once
-- at create or rotate.
-- ====================================
CREATE TABLE calendar_public_shares (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  created_by_user_id INT UNSIGNED NULL COMMENT 'Audit trail; ownership is workspace-level so shares survive creator removal',

  token_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of URL token; plaintext returned once at create/rotate',
  title VARCHAR(255) NOT NULL COMMENT 'Public-facing page title',
  description TEXT NULL COMMENT 'Public-facing description (markdown)',
  icon_url VARCHAR(2048) NULL COMMENT 'Public-facing icon image URL',
  cover_url VARCHAR(2048) NULL COMMENT 'Public-facing cover image URL',

  timezone VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'UTC' COMMENT 'Display tz for the public page; defaults to workspace tz at create',
  show_holidays_country CHAR(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'ISO 3166-1 alpha-2; NULL = no holiday overlay',
  expires_at DATETIME(3) NULL COMMENT 'NULL = never expires',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order within workspace admin UI',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag (soft-disable)',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendar_public_shares_public_id (public_id),
  UNIQUE KEY uniq_calendar_public_shares_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_calendar_public_shares_token_hash (token_hash),
  KEY idx_calendar_public_shares_workspace (workspace_id, enabled),
  KEY idx_calendar_public_shares_expires_at (expires_at),

  CONSTRAINT fk_calendar_public_shares_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_public_shares_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Workspace-owned publishable read-only share pages';

-- >>> calendar_subscriptions.sql
-- ====================================
-- calendar_subscriptions
-- One user's private display preferences for a calendar: their own colour
-- override and whether the layer is toggled on in their sidebar.
--
-- Not an ACL axis, and deliberately so. Access lives in calendar_members;
-- a row here grants nothing and its absence denies nothing. The split
-- keeps a personal preference — which its own user changes freely — from
-- being a permission write.
-- ====================================
CREATE TABLE calendar_subscriptions (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  calendar_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendars.id',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  display_color VARCHAR(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '#4285F4' COMMENT 'Per-subscriber private display color',

  visible BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Whether this calendar layer is shown in UI',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order in sidebar',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendar_subscriptions_public_id (public_id),
  UNIQUE KEY uniq_calendar_subscriptions_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_calendar_subscriptions_calendar_user (calendar_id, user_id),
  KEY idx_calendar_subscriptions_user_workspace (user_id, workspace_id),
  KEY idx_calendar_subscriptions_workspace_calendar (workspace_id, calendar_id),

  CONSTRAINT fk_calendar_subscriptions_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_subscriptions_calendar FOREIGN KEY (calendar_id) REFERENCES calendars(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_subscriptions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Per-user display preferences for a calendar (color, visibility). Not an ACL axis — event-level visibility is the only ws-internal ACL.';

-- >>> calendars.sql
-- ====================================
-- calendars
-- Calendar containers. Who may reach one is calendar_members; what a
-- viewer is allowed to see inside it is the event's own visibility.
--
-- There is deliberately no 'shared' kind. `kind` says where a
-- calendar's contents come from, and sharing is not a source: the
-- number of people who can reach a calendar is a count of
-- calendar_members rows, and encoding it a second time in an enum
-- gives the two encodings a way to disagree. What does change with
-- sharing is owner_user_id — see the column comment.
-- ====================================
CREATE TABLE calendars (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',

  kind ENUM('personal','system') NOT NULL DEFAULT 'personal' COMMENT 'Where the contents come from: personal (written by people through the API) or system (populated from a provider feed identified by system_slug, and read-only to users). Not an audience: see the table comment.',
  name VARCHAR(255) NOT NULL COMMENT 'Display name',
  description TEXT NULL COMMENT 'Optional description',
  color VARCHAR(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '#4285F4' COMMENT 'Default hex color',
  cover_url VARCHAR(2048) NULL COMMENT 'Cover image URL',

  owner_user_id INT UNSIGNED NULL COMMENT 'The user this calendar belongs to, or NULL when it belongs to no one in particular: a system feed, or a calendar shared by a group that outlives any single member. NULL is not cosmetic — the FK cascades, so naming an owner means deleting that user deletes the calendar and every event in it. A group calendar must leave this NULL or one departure takes everyone else''s history with it.',
  system_slug VARCHAR(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'For system calendars: provider identifier (e.g., holidays.jp)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendars_public_id (public_id),
  UNIQUE KEY uniq_calendars_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_calendars_system_slug (workspace_id, system_slug),
  KEY idx_calendars_workspace_id_kind (workspace_id, kind),

  CONSTRAINT fk_calendars_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendars_owner FOREIGN KEY (owner_user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Calendar containers. Access is calendar_members; kind is the source of the contents, not the audience. owner_user_id NULL means the calendar outlives any single member.';

-- >>> events.sql
-- ====================================
-- events
-- Append-only event log. All workspace state transitions flow through this
-- table, and every other process on the database reads it rather than
-- polling: it is the only channel two independently deployed products
-- share. The API offers no DELETE endpoint; purgeWorkspace is the sole
-- deletion path (test fixtures only).
--
-- Consumers tail the log with `WHERE id > last_seen`. AUTO_INCREMENT
-- assigns an id when the INSERT runs but the row stays invisible until
-- its transaction commits, so a row can appear below an id that has
-- already been read. A tailer that advances straight to the highest id
-- it has seen drops those rows permanently; it must re-read from below
-- its high-water mark until a row has had time to commit.
-- ====================================
CREATE TABLE events (
  -- BIGINT UNSIGNED is a deliberate exception to the project default
  -- (INT UNSIGNED for IDs). Justification: this is an append-only event log
  -- expected to grow indefinitely; the ~4.29B INT UNSIGNED ceiling is
  -- reachable in long-lived deployments. Any FK a product layer points at
  -- this column must match the type.
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed; BIGINT UNSIGNED for unbounded append-only growth',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  task_id INT UNSIGNED NULL COMMENT 'Internal FK to tasks.id when the event targets a task',
  calendar_id INT UNSIGNED NULL COMMENT 'Internal FK to calendars.id when the event targets a calendar or something inside one. The symmetric counterpart of task_id, and the reason a per-calendar activity feed can read the log directly instead of keeping a second history table that would drift from it.',
  triggered_by_signal_id INT UNSIGNED NULL COMMENT 'Internal FK to signals.id; set when this event was emitted by the Applier in response to a judged signal. Provides full traceability from external input to task event. Belongs to a product layer: NULL in a deployment without one.',
  actor_user_id INT UNSIGNED NULL COMMENT 'Acting user.id (null for system/bot actions). Mutually exclusive with actor_agent_id and actor_system_source: exactly one of the three actor sources is set per row (both NULL is also legal for legacy "system actor"). The mutual-exclusion rule is enforced by query design and handler validation, not a CHECK constraint, because all three FK referential actions use ON DELETE SET NULL and MySQL 8.4 forbids CHECK constraints referencing columns used in FK referential actions. Every INSERT must therefore bind exactly one of the three, chosen by who is acting: a person, an agent, or a background process.',
  actor_agent_id INT UNSIGNED NULL COMMENT 'Acting ai_agents.id when the event was produced by an AI agent (judge / task agent). See actor_user_id comment for the three-way exclusion rule.',
  actor_system_source VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'Third actor source, for events emitted by a background process rather than a person or an agent. Free-form and namespaced by the writer, e.g. `worker:scheduler` or `worker:retention`. Not an FK because such a process has no row in the database. See actor_user_id comment for the three-way exclusion rule.',
  reverses_event_id BIGINT UNSIGNED NULL COMMENT 'Internal FK to events.id. Non-NULL means this event is a compensating reverse of another event (e.g., user undoing an auto-completion). A projection reading the log cancels both events out. The log is immutable: a reversal is a new row, never an UPDATE or DELETE of the original.',

  type VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Event type (e.g., task.created, signal.attached, signal.judged)',
  payload_json JSON NOT NULL CHECK (JSON_VALID(payload_json)) COMMENT 'Event payload',
  occurred_at DATETIME(3) NOT NULL COMMENT 'Logical time of the event (millisecond precision; ties broken by id)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_events_public_id (public_id),
  UNIQUE KEY uniq_events_workspace_public_id (workspace_id, public_id),
  KEY idx_events_workspace_id_occurred_at (workspace_id, occurred_at),
  KEY idx_events_workspace_id_task_id_occurred_at (workspace_id, task_id, occurred_at),
  KEY idx_events_workspace_id_calendar_id_occurred_at (workspace_id, calendar_id, occurred_at),
  KEY idx_events_workspace_id_type (workspace_id, type),
  KEY idx_events_workspace_id_actor_agent_id (workspace_id, actor_agent_id),
  KEY idx_events_triggered_by_signal (triggered_by_signal_id),
  -- UNIQUE guards against duplicate compensating reversals: two concurrent
  -- reverses of the same event would otherwise both insert a compensating
  -- row and double-cancel in any projection over the log. MySQL treats
  -- multiple NULLs as distinct, so ordinary (non-reverse) events with
  -- reverses_event_id IS NULL are unaffected; only genuine reverses dedupe.
  UNIQUE KEY uniq_events_reverses (workspace_id, reverses_event_id),

  -- fk_events_task, fk_events_actor_agent and fk_events_triggered_by_signal
  -- are NOT declared here. Their columns are core, so every writer produces
  -- rows of the same shape, but `tasks`, `ai_agents` and `signals` belong to
  -- a product layer and a foreign key cannot point at a table that may not
  -- exist. The layer owning those tables adds the three constraints from
  -- its own constraints/ directory; elsewhere the columns are always NULL.
  CONSTRAINT fk_events_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_events_actor FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL,
  -- Unlike task_id this key can be declared here: calendars is core, so
  -- it exists in every deployment. SET NULL keeps the history of a
  -- deleted calendar readable — who removed it is the part worth
  -- keeping — while the log stays append-only.
  CONSTRAINT fk_events_calendar FOREIGN KEY (calendar_id) REFERENCES calendars(id) ON DELETE SET NULL,
  CONSTRAINT fk_events_reverses FOREIGN KEY (reverses_event_id) REFERENCES events(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Append-only event log';

-- >>> identities.sql
-- ====================================
-- identities
-- Authentication credentials for users. A user can have multiple
-- identities: one local (password) plus zero or more OIDC providers.
-- ====================================
CREATE TABLE identities (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  provider ENUM('local','google','github','microsoft','generic_oidc') NOT NULL COMMENT 'Identity provider kind',
  subject VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Provider subject / external ID (ASCII)',
  password_hash CHAR(97) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'Argon2id encoded hash, only for provider=local', -- argon2id encoded form (97 chars)
  mfa_secret_ciphertext VARBINARY(512) NULL COMMENT 'Encrypted TOTP secret (AES-256-GCM)',
  mfa_confirmed_at DATETIME(3) NULL COMMENT 'When the TOTP enrollment was confirmed by submitting a valid code',
  mfa_last_step BIGINT UNSIGNED NULL COMMENT 'Last accepted TOTP time-step (unix/period). RFC 6238 5.2 one-time-use: a code whose step is <= this value is rejected as a replay',
  failed_attempts INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Consecutive failed login attempts',
  locked_until_at DATETIME(3) NULL COMMENT 'Lockout expiry timestamp',
  last_used_at DATETIME(3) NULL COMMENT 'Last successful authentication time',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_identities_public_id (public_id),
  UNIQUE KEY uniq_identities_provider_subject (provider, subject),
  KEY idx_identities_user_id (user_id),

  CONSTRAINT fk_identities_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='User authentication identities';

-- >>> instance_admins.sql
-- ====================================
-- instance_admins
-- Instance-wide admin grants. NOT workspace-scoped: an instance admin can
-- act across every workspace on this deployment.
-- ====================================
CREATE TABLE instance_admins (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',
  granted_by_user_id INT UNSIGNED NULL COMMENT 'Internal FK to users.id (granter, null for bootstrap)',

  granted_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Time the grant was created',
  revoked_at DATETIME(3) NULL COMMENT 'Explicit revocation time',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_instance_admins_public_id (public_id),
  UNIQUE KEY uniq_instance_admins_user_id (user_id),

  CONSTRAINT fk_instance_admins_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_instance_admins_granted_by FOREIGN KEY (granted_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Instance-wide admin grants';

-- >>> instance_audit_logs.sql
-- ====================================
-- instance_audit_logs
-- Instance-wide audit trail for operations that cross workspaces or affect
-- the deployment itself (instance admin grants, workspace create/delete,
-- global setting changes). Not workspace-scoped.
-- ====================================
CREATE TABLE instance_audit_logs (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  actor_user_id INT UNSIGNED NULL COMMENT 'Actor user.id (null for system)',

  action VARCHAR(128) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Action identifier (e.g., instance_admin.grant)',
  target_workspace_id INT UNSIGNED NULL COMMENT 'Affected workspace.id when applicable',
  target_resource_type VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'Target resource type',
  target_resource_public_id BINARY(16) NULL COMMENT 'Target resource public_id when available',
  ip_address VARBINARY(16) NULL COMMENT 'Packed IPv4/IPv6 address',
  user_agent VARCHAR(512) NULL COMMENT 'Client user agent',
  payload_json JSON NULL COMMENT 'Redacted payload (no secrets)',
  occurred_at DATETIME(3) NOT NULL COMMENT 'Logical occurrence time (millisecond precision; ties broken by id)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_instance_audit_logs_public_id (public_id),
  KEY idx_instance_audit_logs_occurred_at (occurred_at),
  KEY idx_instance_audit_logs_action (action),
  KEY idx_instance_audit_logs_target_workspace_id (target_workspace_id),

  CONSTRAINT fk_instance_audit_logs_actor FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_instance_audit_logs_workspace FOREIGN KEY (target_workspace_id) REFERENCES workspaces(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Instance-wide audit log';

-- >>> instance_settings.sql
-- ====================================
-- instance_settings
-- Instance-level dynamic settings. NOT workspace-scoped: these settings
-- apply globally to the entire deployment.
-- ====================================
CREATE TABLE instance_settings (
  id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id       BINARY(16)     NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  setting_key     VARCHAR(128) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Setting identifier',
  setting_value   TEXT           NOT NULL COMMENT 'Current value as text',
  updated_by_user_id INT UNSIGNED NULL COMMENT 'Last modifier user.id',
  sort_weight     INT            NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes           TEXT           NULL COMMENT 'Admin notes',
  enabled         BOOLEAN        NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at      TIMESTAMP(3)   DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at      DATETIME(3)    NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_instance_settings_public_id (public_id),
  UNIQUE KEY uniq_instance_settings_key (setting_key),

  CONSTRAINT fk_instance_settings_user
    FOREIGN KEY (updated_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Instance-level dynamic settings';

-- >>> magic_link_tokens.sql
-- ====================================
-- magic_link_tokens
-- Passwordless magic-link authentication tokens. Only the SHA-256 hash
-- of the token is stored; the plaintext URL is sent to the user exactly
-- once via email.
-- ====================================
CREATE TABLE magic_link_tokens (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  token_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of the token',
  expires_at DATETIME(3) NOT NULL COMMENT 'Token expiry time',
  used_at DATETIME(3) NULL COMMENT 'Time the token was consumed',
  ip_address VARBINARY(16) NULL COMMENT 'Packed IPv4/IPv6 address at creation',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_magic_link_tokens_public_id (public_id),
  UNIQUE KEY uniq_magic_link_tokens_token_hash (token_hash),
  KEY idx_magic_link_tokens_user_id (user_id),
  KEY idx_magic_link_tokens_expires_at (expires_at),

  CONSTRAINT fk_magic_link_tokens_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Passwordless magic-link tokens';

-- >>> oauth_states.sql
-- ====================================
-- oauth_states
-- Short-lived CSRF-protection state tokens for the personal OAuth
-- flow (POST /me/integrations/{provider}/connect → GET /oauth/
-- callback/{provider}). A row is inserted when the user clicks
-- "Connect", and deleted atomically when the callback handler
-- consumes the matching state. Rows expire after 15 minutes; the
-- callback refuses stale rows.
-- ====================================
CREATE TABLE oauth_states (
  state CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL PRIMARY KEY COMMENT 'Random 32-byte token, hex-encoded',

  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id — the user who started the connect flow',
  provider ENUM('github','slack','google_calendar','discord') NOT NULL COMMENT 'Which provider this state belongs to. ''discord'' is required for the personal Discord presence-binding flow (Phase 8 presence-discord gateway).',
  redirect_to VARCHAR(512) NULL COMMENT 'Optional client-supplied return URL to send the user to after the callback completes',

  expires_at DATETIME(3) NOT NULL COMMENT 'Hard expiry; callback handler rejects rows past this timestamp',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  KEY idx_oauth_states_expires_at (expires_at),

  CONSTRAINT fk_oauth_states_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Short-lived OAuth CSRF state tokens for personal integrations';

-- >>> personal_access_tokens.sql
-- ====================================
-- personal_access_tokens
-- User-scoped API tokens for the REST API and CLI (`tnk`).
-- Only the SHA-256 hash of the bearer token is stored; the plaintext is
-- shown to the user exactly once at creation time.
-- ====================================
CREATE TABLE personal_access_tokens (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id (token owner)',

  name VARCHAR(255) NOT NULL COMMENT 'Human-readable label',
  token_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of the bearer token',
  token_prefix CHAR(8) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Leading chars shown as hint',
  scopes_json JSON NOT NULL COMMENT 'Array of granted API scopes',
  expires_at DATETIME(3) NULL COMMENT 'Expiry time (null = never)',
  last_used_at DATETIME(3) NULL COMMENT 'Last successful use',
  revoked_at DATETIME(3) NULL COMMENT 'Explicit revocation time',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_personal_access_tokens_public_id (public_id),
  UNIQUE KEY uniq_personal_access_tokens_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_personal_access_tokens_token_hash (token_hash),
  KEY idx_personal_access_tokens_workspace_id_user_id (workspace_id, user_id),
  KEY idx_personal_access_tokens_expires_at (expires_at),

  CONSTRAINT fk_personal_access_tokens_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_personal_access_tokens_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='User personal access tokens for REST/CLI';

-- >>> sessions.sql
-- ====================================
-- sessions
-- Refresh-token backed user sessions. Access tokens are stateless JWT;
-- this table only tracks the refresh token hash and its metadata.
-- ====================================
CREATE TABLE sessions (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  refresh_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of refresh token',
  user_agent VARCHAR(512) NULL COMMENT 'Client user agent at issue time',
  ip_address VARBINARY(16) NULL COMMENT 'Packed IPv4/IPv6 address at issue time',
  expires_at DATETIME(3) NOT NULL COMMENT 'Refresh token expiry',
  revoked_at DATETIME(3) NULL COMMENT 'Explicit revocation time',
  last_used_at DATETIME(3) NULL COMMENT 'Last refresh time',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_sessions_public_id (public_id),
  UNIQUE KEY uniq_sessions_refresh_hash (refresh_hash),
  KEY idx_sessions_user_id_expires_at (user_id, expires_at),

  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Refresh-token backed sessions';

-- >>> storage_objects.sql
-- ====================================
-- storage_objects
-- Content-addressed metadata index for blobs that physically live in MinIO
-- (S3-compatible object storage). One row per unique (scope, sha256) tuple
-- so that uploading the same file twice within a scope reuses the underlying
-- object and only bumps ref_count.
--
-- Scope is exclusive: a row either belongs to a workspace (task / calendar
-- event attachments) or to a single user (avatar). The check constraint
-- enforces exactly one of workspace_id / owner_user_id is non-null.
--
-- Lifecycle: creating a referencing row (attachments / users.avatar_*) bumps
-- ref_count, deleting one decrements it. A background sweeper hard-deletes
-- the MinIO object and this row when ref_count reaches 0. FKs from referrers
-- use ON DELETE RESTRICT so we never lose track of a still-referenced blob.
-- ====================================
CREATE TABLE storage_objects (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NULL COMMENT 'Internal FK to workspaces.id; non-null for workspace-scoped blobs (task/calendar attachments). Mutually exclusive with owner_user_id.',
  owner_user_id INT UNSIGNED NULL COMMENT 'Internal FK to users.id; non-null for user-scoped blobs (avatar). Mutually exclusive with workspace_id.',

  sha256 BINARY(32) NOT NULL COMMENT 'SHA-256 of the raw blob; basis for content addressing and dedup within a scope',
  byte_size BIGINT UNSIGNED NOT NULL COMMENT 'Size in bytes of the underlying blob',
  content_type VARCHAR(127) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'MIME type recorded at upload time',
  storage_key VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Computed object key in MinIO (e.g. workspace/{wsPublicId}/{sha256_hex} or user/{userPublicId}/{sha256_hex})',
  ref_count INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Number of referencing rows (attachments / users.avatar_storage_object_id); GC eligible when 0',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_storage_objects_public_id (public_id),
  -- Per-scope content dedup. NULLs are distinct in MySQL UNIQUE indexes, so
  -- the workspace-scope and user-scope rows do not interfere with each other.
  UNIQUE KEY uniq_storage_objects_workspace_sha (workspace_id, sha256),
  UNIQUE KEY uniq_storage_objects_user_sha (owner_user_id, sha256),
  UNIQUE KEY uniq_storage_objects_storage_key (storage_key),

  CONSTRAINT fk_storage_objects_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_storage_objects_owner_user FOREIGN KEY (owner_user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT chk_storage_objects_scope_exclusive CHECK (
    (workspace_id IS NOT NULL AND owner_user_id IS NULL) OR
    (workspace_id IS NULL     AND owner_user_id IS NOT NULL)
  )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Content-addressed object storage references; rows shared across attachments via storage_object_id with ref_count GC.';

-- >>> user_recovery_codes.sql
-- ====================================
-- user_recovery_codes
-- One-time recovery codes used to bypass TOTP at login when the user
-- loses access to their authenticator app. Codes are stored as
-- SHA-256 hashes; the plaintext is shown to the user only once at
-- generation time.
-- ====================================
CREATE TABLE user_recovery_codes (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',
  code_hash BINARY(32) NOT NULL COMMENT 'SHA-256 of the normalized recovery code',
  used_at DATETIME(3) NULL COMMENT 'Set when the code is consumed at login',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_user_recovery_codes_user_hash (user_id, code_hash),
  KEY idx_user_recovery_codes_user_used (user_id, used_at),

  CONSTRAINT fk_user_recovery_codes_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='TOTP recovery codes';

-- >>> users.sql
-- ====================================
-- users
-- Account-level principals. Authenticated via identities (local/oidc).
-- Not workspace-scoped; users are global and join workspaces via workspace_members.
-- ====================================
CREATE TABLE users (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',

  email VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Primary email, ASCII only',
  email_verified_at DATETIME(3) NULL COMMENT 'Email verification timestamp',
  display_name VARCHAR(255) NOT NULL COMMENT 'Human-readable name',
  avatar_url VARCHAR(2048) NULL COMMENT 'Avatar image URL; used when the avatar is hosted externally (e.g. OIDC provider)',
  avatar_storage_object_id INT UNSIGNED NULL COMMENT 'FK to storage_objects.id when the user uploaded their own avatar; NULL when avatar_url (external) is used or no avatar is set',
  locale VARCHAR(16) NOT NULL DEFAULT 'en' COMMENT 'Preferred locale tag (BCP 47)',
  timezone VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'UTC' COMMENT 'Preferred IANA timezone (independent of locale)',
  country CHAR(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'ISO 3166-1 alpha-2 country (independent of locale); drives default holiday subscription',
  week_start ENUM('mon','sun','sat') NOT NULL DEFAULT 'mon' COMMENT 'Preferred first day of the week for calendar grids',
  working_days CHAR(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'User override of workspace working_days; NULL = inherit',
  working_hours_start TIME NULL COMMENT 'User override of workspace working_hours_start; NULL = inherit',
  working_hours_end TIME NULL COMMENT 'User override of workspace working_hours_end; NULL = inherit',
  snap_to_working_day ENUM('off','warn','auto') NOT NULL DEFAULT 'warn' COMMENT 'What happens when a task/event lands on a non-working day: off=accept silently, warn=save with badge, auto=itemkit snaps forward to next working day',
  treat_holidays_as_non_working BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'If true, subscribed system (holiday) calendar events count as non-working days',
  theme_preference ENUM('aurora-light','aurora-dark','dotline-light','dotline-dark','glass-light','glass-dark','system') NOT NULL DEFAULT 'system' COMMENT 'UI theme preference',
  calendar_shift_default ENUM('ask','sync_always','task_only_always') NOT NULL DEFAULT 'ask' COMMENT 'Default behaviour when an event linked to safe tasks is shifted: ask=prompt the user every time (current behaviour), sync_always=also shift every linked safe task by the same delta, task_only_always=shift only the event and leave linked tasks alone',
  last_login_at DATETIME(3) NULL COMMENT 'Last successful login',

  -- Notification channel toggles (see /settings/notifications).
  notif_email_digest_enabled     BOOLEAN NOT NULL DEFAULT TRUE  COMMENT 'Weekly digest email',
  notif_email_mention_enabled    BOOLEAN NOT NULL DEFAULT TRUE  COMMENT 'Email when mentioned in comments',
  notif_email_assignment_enabled BOOLEAN NOT NULL DEFAULT TRUE  COMMENT 'Email when assigned to a task',
  notif_email_due_soon_enabled   BOOLEAN NOT NULL DEFAULT TRUE  COMMENT 'Email when owned task is due within 24h',
  notif_web_push_enabled         BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Browser push notifications',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_users_public_id (public_id),
  UNIQUE KEY uniq_users_email (email),
  KEY idx_users_enabled (enabled),
  KEY idx_users_avatar_storage_object (avatar_storage_object_id),

  -- SET NULL: if the underlying storage_objects row is removed (e.g. after
  -- ref_count reaches 0 via a sweeper) the user simply loses their avatar
  -- rather than blocking the deletion.
  CONSTRAINT fk_users_avatar_storage_object FOREIGN KEY (avatar_storage_object_id) REFERENCES storage_objects(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Global user accounts';

-- >>> workspace_invites.sql
-- ====================================
-- workspace_invites
-- Token-based invite links for joining a workspace with a pre-assigned role.
-- The plaintext token is never stored; only its SHA-256 hex hash is persisted.
-- ====================================
CREATE TABLE workspace_invites (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  created_by_user_id INT UNSIGNED NULL COMMENT 'Internal FK to users.id who created the invite',

  token_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of invite token plaintext',
  role ENUM('owner','admin','member','guest') NOT NULL DEFAULT 'member' COMMENT 'Role granted on accept',
  max_uses INT UNSIGNED NULL COMMENT 'NULL = unlimited',
  use_count INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Number of times this invite has been used',
  expires_at DATETIME(3) NULL COMMENT 'NULL = never expires',
  label VARCHAR(255) NULL COMMENT 'Optional human label for the invite link',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_workspace_invites_public_id (public_id),
  UNIQUE KEY uniq_workspace_invites_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_workspace_invites_token_hash (token_hash),
  KEY idx_workspace_invites_workspace_id (workspace_id),
  KEY idx_workspace_invites_expires_at (expires_at),

  CONSTRAINT fk_workspace_invites_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_workspace_invites_created_by FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Token-based workspace invite links';

-- >>> workspace_members.sql
-- ====================================
-- workspace_members
-- M:N between workspaces and users with a workspace-scoped role.
-- ====================================
CREATE TABLE workspace_members (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  role ENUM('owner','admin','member','guest') NOT NULL DEFAULT 'member' COMMENT 'Workspace-level role',
  invited_by_user_id INT UNSIGNED NULL COMMENT 'Inviter user.id',
  invited_at DATETIME(3) NULL COMMENT 'Invitation time',
  joined_at DATETIME(3) NULL COMMENT 'Acceptance time',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_workspace_members_public_id (public_id),
  UNIQUE KEY uniq_workspace_members_workspace_public_id (workspace_id, public_id),
  UNIQUE KEY uniq_workspace_members_workspace_id_user_id (workspace_id, user_id),
  KEY idx_workspace_members_user_id (user_id),

  CONSTRAINT fk_workspace_members_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_workspace_members_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_workspace_members_inviter FOREIGN KEY (invited_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Workspace membership';

-- >>> workspaces.sql
-- ====================================
-- workspaces
-- Top-level tenant boundary. Every workspace-scoped table carries
-- workspace_id as its leading composite index column.
-- ====================================
CREATE TABLE workspaces (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',

  slug VARCHAR(63) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'DNS-label slug (RFC 1035)',
  name VARCHAR(255) NOT NULL COMMENT 'Display name',
  description TEXT NULL COMMENT 'Optional description',
  icon_url VARCHAR(2048) NULL COMMENT 'Icon image URL',

  timezone VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'UTC' COMMENT 'Default IANA timezone for the workspace; user tz overrides per-user',
  country CHAR(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL COMMENT 'ISO 3166-1 alpha-2 country; drives default holiday subscription',
  working_days CHAR(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'MTWTF__' COMMENT 'Per-day flag string Mon..Sun; letter = working, underscore = off. Default MTWTF__ = Mon-Fri.',
  working_hours_start TIME NOT NULL DEFAULT '09:00:00' COMMENT 'Start of workspace working day (local tz)',
  working_hours_end TIME NOT NULL DEFAULT '18:00:00' COMMENT 'End of workspace working day (local tz)',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_workspaces_public_id (public_id),
  UNIQUE KEY uniq_workspaces_slug (slug),
  KEY idx_workspaces_enabled (enabled)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Tenant boundary';

-- >>> album_photos.sql
-- ====================================
-- album_photos
-- Shared photo album pinned to a calendar, optionally to one event.
-- This product's own feature: the contract has no notion of an album,
-- so the table lives in this layer and references core from here.
-- ====================================
CREATE TABLE album_photos (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  calendar_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendars.id',
  calendar_event_id INT UNSIGNED NULL COMMENT 'Internal FK to calendar_events.id when the photo was attached to a specific event',
  uploaded_by_user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  caption VARCHAR(500) NOT NULL DEFAULT '' COMMENT 'Free-form caption',
  content_type VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT 'image/jpeg' COMMENT 'MIME type as uploaded',
  byte_size BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Size in bytes',
  width INT UNSIGNED NULL COMMENT 'Pixel width when known',
  height INT UNSIGNED NULL COMMENT 'Pixel height when known',
  storage_key VARCHAR(1000) NOT NULL COMMENT 'Object key in the blob store',
  taken_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'EXIF capture time, falling back to upload time; the album orders by this rather than by upload order',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Soft-delete flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_album_photos_public_id (public_id),
  UNIQUE KEY uniq_album_photos_workspace_public_id (workspace_id, public_id),
  KEY idx_album_photos_calendar_taken (calendar_id, enabled, taken_at, id),
  KEY idx_album_photos_event (calendar_event_id),
  KEY idx_album_photos_enabled_created (enabled, created_at) COMMENT 'Supports the abandoned-upload sweep',

  CONSTRAINT fk_album_photos_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_album_photos_calendar FOREIGN KEY (calendar_id) REFERENCES calendars(id) ON DELETE CASCADE,
  CONSTRAINT fk_album_photos_uploader FOREIGN KEY (uploaded_by_user_id) REFERENCES users(id) ON DELETE CASCADE,
  -- SET NULL: deleting the event a photo was attached to must not delete
  -- the photo. The album outlives the occasion.
  CONSTRAINT fk_album_photos_event FOREIGN KEY (calendar_event_id) REFERENCES calendar_events(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Shared calendar photo album';

-- >>> avatar_uploads.sql
-- ====================================
-- avatar_uploads
-- Reservations for in-flight avatar uploads.
--
-- A row is created when a presigned URL is handed out and removed once
-- the upload is claimed. It is not the avatar: the finished object is
-- storage_objects, referenced from users.avatar_storage_object_id. This
-- table exists so an upload that is started and abandoned leaves a
-- record with an expiry, which is what the sweeper deletes by.
-- ====================================
CREATE TABLE avatar_uploads (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  sha256 BINARY(32) NOT NULL COMMENT 'Digest of the bytes the client is about to upload. Carried through the reservation because storage_objects is keyed on it, and the digest is not knowable server-side until the object has landed.',
  storage_key VARCHAR(1000) NOT NULL COMMENT 'Object key the presigned URL was issued for; derived from the digest, never from a client-supplied filename',
  content_type VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Declared MIME type',
  byte_size BIGINT UNSIGNED NOT NULL COMMENT 'Declared size in bytes',
  expires_at DATETIME(3) NOT NULL COMMENT 'After this the reservation is abandoned and the object may be swept',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_avatar_uploads_public_id (public_id),
  KEY idx_avatar_uploads_user_expiry (user_id, expires_at),
  KEY idx_avatar_uploads_expiry (expires_at),

  CONSTRAINT fk_avatar_uploads_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='In-flight avatar upload reservations';

-- >>> calendar_invites.sql
-- ====================================
-- calendar_invites
-- Join-by-link invitations to a calendar. The contract covers the two
-- neighbouring cases — a workspace invitation, and a read-only public
-- share page — but not this one: a link that grants calendar membership
-- at a stated role. That is this product's model of sharing, so the
-- table lives in this layer.
-- ====================================
CREATE TABLE calendar_invites (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  workspace_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to workspaces.id',
  calendar_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to calendars.id',
  created_by_user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  token_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of the invite token. The plaintext is shown once at creation and never stored, so a database read cannot yield a working link.',
  role ENUM('owner','manager','editor','viewer') NOT NULL DEFAULT 'viewer' COMMENT 'Role granted on acceptance. Matches calendar_members.role, and defaults to the least privilege so a link created without naming one cannot hand out more than reading.',
  max_uses INT UNSIGNED NULL COMMENT 'Acceptance limit; NULL = unlimited',
  use_count INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Acceptances so far',
  is_public BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'TRUE publishes the calendar read-only: the link can be viewed but not joined, and role is ignored. FALSE grants membership at role on acceptance.',
  expires_at DATETIME(3) NULL COMMENT 'Expiry; NULL = does not expire',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Revocation flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_calendar_invites_public_id (public_id),
  UNIQUE KEY uniq_calendar_invites_token_hash (token_hash),
  KEY idx_calendar_invites_calendar (calendar_id, enabled),

  CONSTRAINT fk_calendar_invites_workspace FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_invites_calendar FOREIGN KEY (calendar_id) REFERENCES calendars(id) ON DELETE CASCADE,
  CONSTRAINT fk_calendar_invites_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE CASCADE,

  CONSTRAINT chk_calendar_invites_uses CHECK (max_uses IS NULL OR use_count <= max_uses)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Join-by-link calendar invitations';

-- >>> email_verifications.sql
-- ====================================
-- email_verifications
-- Single-use tokens proving a person can read the mailbox they registered
-- with.
--
-- Separate from password_resets for the same reason password_resets is
-- separate from magic_link_tokens: one table would mean a token minted to
-- confirm an address is also accepted to replace a credential.
--
-- What the proof is for: provider sign-in links a verified provider email to
-- an existing account with the same address. Without a proof that the
-- existing account's own address belongs to its owner, anyone can register
-- someone else's address first and inherit the account they later sign in to.
-- ====================================
CREATE TABLE email_verifications (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  email VARCHAR(255) NOT NULL COMMENT 'Address the token was sent to. Recorded so a token stops applying once the account changes address, rather than confirming whatever address is current at redemption time.',
  token_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of the token; the plaintext is emailed once and never stored',
  expires_at DATETIME(3) NOT NULL COMMENT 'Expiry',
  used_at DATETIME(3) NULL COMMENT 'Redemption time; a non-NULL value makes the token spent',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_email_verifications_public_id (public_id),
  UNIQUE KEY uniq_email_verifications_token_hash (token_hash),
  KEY idx_email_verifications_user (user_id, expires_at),
  KEY idx_email_verifications_expiry (expires_at),

  CONSTRAINT fk_email_verifications_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Single-use email ownership proofs';

-- >>> oauth_allowed_emails.sql
-- ====================================
-- oauth_allowed_emails
-- Individual exceptions to the domain restriction on OAuth sign-in.
-- When a domain allow-list is configured, an address listed here may
-- sign in even though its domain is not.
-- ====================================
CREATE TABLE oauth_allowed_emails (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',

  email VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Allowed address, ASCII only to match users.email',
  reason VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'Why this address is excepted; the list is unreadable a year later without it',
  created_by_user_id INT UNSIGNED NULL COMMENT 'Operator who added it',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag; FALSE withdraws the exception without losing the record of it',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_oauth_allowed_emails_public_id (public_id),
  UNIQUE KEY uniq_oauth_allowed_emails_email (email),

  CONSTRAINT fk_oauth_allowed_emails_creator FOREIGN KEY (created_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Per-address exceptions to the OAuth domain restriction';

-- >>> oauth_provider_configs.sql
-- ====================================
-- oauth_provider_configs
-- Per-provider OAuth client credentials, editable from the admin panel.
--
-- The contract's identities table records which provider authenticated a
-- user; it says nothing about how this deployment talks to that provider.
-- That is operator configuration and lives here. It is deliberately not
-- instance_settings: the client secret needs its own encrypted column
-- rather than a TEXT value alongside settings meant to be read in the
-- clear.
-- ====================================
CREATE TABLE oauth_provider_configs (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',

  provider ENUM('google','github','microsoft','generic_oidc','line') NOT NULL COMMENT 'Provider this configuration is for. Overlaps identities.provider but is not a subset of it: a provider can be configured before anyone has signed in with it, and local has no configuration.',
  client_id VARCHAR(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '' COMMENT 'OAuth client identifier',
  client_secret_ciphertext VARBINARY(512) NOT NULL COMMENT 'Encrypted client secret (AES-256-GCM). Never returned by the API.',
  updated_by_user_id INT UNSIGNED NULL COMMENT 'Last operator to change it',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Whether this provider is offered at sign-in',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_oauth_provider_configs_public_id (public_id),
  UNIQUE KEY uniq_oauth_provider_configs_provider (provider),

  CONSTRAINT fk_oauth_provider_configs_updater FOREIGN KEY (updated_by_user_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Per-provider OAuth client configuration';

-- >>> password_resets.sql
-- ====================================
-- password_resets
-- Single-use password reset tokens.
--
-- Not magic_link_tokens, which the contract already defines: that token
-- signs someone in, this one lets them replace a credential. Sharing one
-- table would mean a token minted for either purpose is accepted for
-- both, and a reset link leaked from an inbox would become a login.
-- ====================================
CREATE TABLE password_resets (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',
  user_id INT UNSIGNED NOT NULL COMMENT 'Internal FK to users.id',

  token_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of the token; the plaintext is emailed once and never stored',
  expires_at DATETIME(3) NOT NULL COMMENT 'Expiry',
  used_at DATETIME(3) NULL COMMENT 'Redemption time; a non-NULL value makes the token spent',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_password_resets_public_id (public_id),
  UNIQUE KEY uniq_password_resets_token_hash (token_hash),
  KEY idx_password_resets_user (user_id, expires_at),

  CONSTRAINT fk_password_resets_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Single-use password reset tokens';

-- >>> signin_states.sql
-- ====================================
-- signin_states
-- Short-lived state for an OAuth sign-in that is still in flight.
--
-- Not the contract's oauth_states, which records a signed-in user linking
-- an external service and therefore requires a user_id. Here there is no
-- user yet: that is the whole point of the round trip. Reusing one table
-- would mean either making its user_id nullable for everyone, or inventing
-- a placeholder user for every abandoned login.
-- ====================================
CREATE TABLE signin_states (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY COMMENT 'Internal PK, never exposed',
  public_id BINARY(16) NOT NULL COMMENT 'UUID v7, the only externally visible ID',

  state_hash CHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'SHA-256 hex of the state parameter. Hashed like every other bearer value here, so a database read cannot be replayed against the provider.',
  provider ENUM('google','github','microsoft','generic_oidc','line') NOT NULL COMMENT 'Provider the round trip is with',
  redirect_to VARCHAR(512) NULL COMMENT 'Where to send the browser after a successful sign-in. Validated against an allow-list before use: an unchecked value here is an open redirect.',
  code_verifier VARCHAR(128) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '' COMMENT 'PKCE verifier, exchanged for the code',
  nonce VARCHAR(64) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '' COMMENT 'OIDC nonce, checked against the id_token claim to bind the token to this request',
  expires_at DATETIME(3) NOT NULL COMMENT 'After this the round trip is abandoned',

  sort_weight INT NOT NULL DEFAULT 0 COMMENT 'Display order',
  notes TEXT NULL COMMENT 'Admin notes',
  enabled BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Enabled flag',
  updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),

  UNIQUE KEY uniq_signin_states_public_id (public_id),
  UNIQUE KEY uniq_signin_states_state_hash (state_hash),
  KEY idx_signin_states_expires (expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='In-flight OAuth sign-in state';

-- >>> identities_provider.sql
-- ====================================
-- identities.provider — product-layer widening
--
-- The shared contract enumerates the providers every product implementing it
-- must accept. This product also offers LINE sign-in, which the contract does
-- not name, so the value is added here rather than in core/: widening an ENUM
-- in the product layer keeps the vendored contract byte-identical to upstream
-- while still letting a LINE identity be stored.
--
-- Without this the provider is rejected by the column's own constraint, the
-- sign-in transaction rolls back, and the failure surfaces as a raw error in
-- the middle of a browser redirect.
--
-- oauth_provider_configs.provider already lists 'line' in its own definition
-- because that table belongs to this layer.
-- ====================================
ALTER TABLE identities
  MODIFY COLUMN provider
    ENUM('local','google','github','microsoft','generic_oidc','line')
    NOT NULL COMMENT 'Identity provider kind';

DROP TRIGGER IF EXISTS `trg_calendar_events_projection_guard_del`;
DROP TRIGGER IF EXISTS `trg_calendar_events_projection_guard_ins`;
DROP TRIGGER IF EXISTS `trg_calendar_events_projection_guard_upd`;

-- >>> trg_calendar_events_projection_guard_del.sql
-- ====================================
-- trg_calendar_events_projection_guard_del
-- DELETE half of the calendar_events projection guard. See
-- trg_calendar_events_projection_guard_upd for the full rationale.
--
-- Nothing in the product hard-deletes a calendar event: removal is
-- enabled = FALSE, which the UPDATE guard already covers. This trigger
-- exists for the writer that reaches past the product and issues a real
-- DELETE, which would drop a task's projection with no compensating
-- row in `events` and no way to notice afterwards.
--
-- Workspace and calendar teardown are unaffected: MySQL does not
-- activate triggers for rows removed by a foreign key referential
-- action.
-- ====================================
DELIMITER $$

CREATE TRIGGER trg_calendar_events_projection_guard_del
BEFORE DELETE ON calendar_events
FOR EACH ROW
BEGIN
  IF OLD.task_id IS NOT NULL AND @nf_item_projection_engine IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'task-projected calendar events may only be deleted by the item projection engine';
  END IF;
END$$

DELIMITER ;

-- >>> trg_calendar_events_projection_guard_ins.sql
-- ====================================
-- trg_calendar_events_projection_guard_ins
-- INSERT half of the calendar_events projection guard. See
-- trg_calendar_events_projection_guard_upd for the full rationale.
--
-- Enforces, unconditionally:
--   (task_id IS NULL) = (task_role IS NULL)
--   task_id IS NULL OR recurrence_rule IS NULL
--   (recurrence_parent_id IS NULL) = (recurrence_original_start IS NULL)
--   recurrence_parent_id IS NULL OR recurrence_rule IS NULL
--   recurrence_parent_id IS NULL OR task_id IS NULL
--
-- and, unless @nf_item_projection_engine is set: a row may not be
-- created already linked to a task.
-- ====================================
DELIMITER $$

CREATE TRIGGER trg_calendar_events_projection_guard_ins
BEFORE INSERT ON calendar_events
FOR EACH ROW
BEGIN
  IF (NEW.task_id IS NULL) <> (NEW.task_role IS NULL) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'calendar_events.task_id and task_role must be set or cleared together';
  END IF;

  IF NEW.task_id IS NOT NULL AND NEW.recurrence_rule IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'a task-projected calendar event may not carry a recurrence rule';
  END IF;

  IF (NEW.recurrence_parent_id IS NULL) <> (NEW.recurrence_original_start IS NULL) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'calendar_events.recurrence_parent_id and recurrence_original_start must be set or cleared together';
  END IF;

  IF NEW.recurrence_parent_id IS NOT NULL AND NEW.recurrence_rule IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'an occurrence override may not carry a recurrence rule of its own';
  END IF;

  IF NEW.recurrence_parent_id IS NOT NULL AND NEW.task_id IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'a task-projected calendar event may not be an occurrence override';
  END IF;

  IF NEW.task_id IS NOT NULL AND @nf_item_projection_engine IS NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'task-projected calendar events may only be written by the item projection engine';
  END IF;
END$$

DELIMITER ;

-- >>> trg_calendar_events_projection_guard_upd.sql
-- ====================================
-- trg_calendar_events_projection_guard_upd
-- Keeps a task-projected calendar event in step with the task it
-- projects, from the database rather than from application code.
--
-- Two classes of rule live here.
--
-- Unconditional shape invariants. These would be CHECK constraints,
-- but MySQL 8.4+ forbids a CHECK that references a column used in a
-- foreign key referential action, and task_id carries ON DELETE SET
-- NULL. A trigger has no such restriction:
--
--   (task_id IS NULL) = (task_role IS NULL)
--   task_id IS NULL OR recurrence_rule IS NULL
--   (recurrence_parent_id IS NULL) = (recurrence_original_start IS NULL)
--   recurrence_parent_id IS NULL OR recurrence_rule IS NULL
--   recurrence_parent_id IS NULL OR task_id IS NULL
--
-- Ownership of the projection. task_id / task_role and the columns
-- that mirror a task field (title, start_at, end_at, and the
-- enabled soft-delete flag) may only be written by the projection
-- engine, which moves the task and the event together inside one
-- transaction and appends the matching item.* row to `events`. A
-- writer that changes them directly desyncs the pair and emits no
-- domain event, which is exactly the drift the reconciler reports as
-- item_inconsistency_total.
--
-- Columns with no task-side counterpart (memo, location, visibility,
-- show_as, url, block_label, ...) stay freely editable on a projected
-- row: they carry no invariant, so guarding them would only make the
-- calendar UI lie about what it can offer.
--
-- The engine opts in by setting @nf_item_projection_engine = 1 on the
-- connection before its write and clearing it afterwards; the variable
-- is session-scoped, so a fresh connection is always guarded. In a
-- deployment without the flow layer task_id is always NULL and none of
-- these branches can fire.
--
-- Comparisons use <=> because start_at / end_at / task_id are nullable
-- and `<>` yields NULL — never true — as soon as either side is NULL.
-- ====================================
DELIMITER $$

CREATE TRIGGER trg_calendar_events_projection_guard_upd
BEFORE UPDATE ON calendar_events
FOR EACH ROW
BEGIN
  IF (NEW.task_id IS NULL) <> (NEW.task_role IS NULL) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'calendar_events.task_id and task_role must be set or cleared together';
  END IF;

  IF NEW.task_id IS NOT NULL AND NEW.recurrence_rule IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'a task-projected calendar event may not carry a recurrence rule';
  END IF;

  IF (NEW.recurrence_parent_id IS NULL) <> (NEW.recurrence_original_start IS NULL) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'calendar_events.recurrence_parent_id and recurrence_original_start must be set or cleared together';
  END IF;

  IF NEW.recurrence_parent_id IS NOT NULL AND NEW.recurrence_rule IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'an occurrence override may not carry a recurrence rule of its own';
  END IF;

  IF NEW.recurrence_parent_id IS NOT NULL AND NEW.task_id IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'a task-projected calendar event may not be an occurrence override';
  END IF;

  IF @nf_item_projection_engine IS NULL THEN
    IF NOT (NEW.task_id <=> OLD.task_id) OR NOT (NEW.task_role <=> OLD.task_role) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'the task projection link may only be changed by the item projection engine';
    END IF;

    IF OLD.task_id IS NOT NULL
       AND (NOT (NEW.title <=> OLD.title)
         OR NOT (NEW.start_at <=> OLD.start_at)
         OR NOT (NEW.end_at <=> OLD.end_at)
         OR NOT (NEW.enabled <=> OLD.enabled)) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'title, start_at, end_at and enabled mirror the linked task and may only be written by the item projection engine';
    END IF;
  END IF;
END$$

DELIMITER ;

SET UNIQUE_CHECKS = 1;
SET FOREIGN_KEY_CHECKS = 1;
